public static String[] toNoNullStringArray(Object[] array) {
    // Check if the array is null or empty
    if (array == null || array.length == 0) {
        return new String[0];
    }

    // Create a new array without null elements
    String[] noNullArray = new String[array.length];
    int i = 0;
    for (Object element : array) {
        if (element != null) {
            noNullArray[i++] = element.toString();
        }
    }

    // Reduce the size of the new array if necessary
    if (i != noNullArray.length) {
        String[] noNullArrayTrimmed = new String[i];
        System.arraycopy(noNullArray, 0, noNullArrayTrimmed, 0, i);
        return noNullArrayTrimmed;
    } else {
        return noNullArray;
    }
}

