public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

List<ThreadSnapshot> threadSnapshots = new ArrayList<ThreadSnapshot>();

// Open the file for reading
try (FileInputStream fis = new FileInputStream(file)) {

    // Parse the file contents
    HprofParser parser = new HprofParser(fis);

    // Iterate over the time ranges
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {

        // Parse the snapshots within the current time range
        List<ThreadSnapshot> snapshots = parser.parseSnapshots(timeRange.getTimeRangeInMillis());

        // Add the snapshots to the list
        threadSnapshots.addAll(snapshots);
    }
}

// Return the list of thread snapshots
return threadSnapshots;
}
